435-//# sourceURL=jet-popup-frontend-js-extra </script> <script id="jet-popup-frontend-js" src="https://www.apeejay.edu/architecture/wp-content/uploads/siteground-optimizer-assets/jet-popup-frontend.min.js?ver=2.2.2"></script> <script id="jet-engine-compatibility-angie-js-extra"> var jetEngineCompatibilityAngie = {"features":[{"id":"tool-add-cct","name":"tool-add-cct","label":"Add Custom Content Type","description":"This feature allows you to register a new Custom Content Type. Custom Content Type is a performant content storage, which can replace Custom Post Types for some cases. All the Custom Content Type data stored in the separate DB table, so it`s an efficient way to store large amounts of the information.","type":"tool","input_schema":{"type":"object","properties":{"name":{"type":"string","description":"The name of the Custom Content Type."},"slug":{"type":"string","description":"The slug of the Custom Content Type. Should contain only lowercase letters and underscores."},"fields":{"type":"array","description":"The fields of the Custom Content Type. Each field should have a name, type, is_key_field flag (yes/no) and optionally options for select, checkbox, and radio types.","items":{"type":"object","properties":{"field_name":{"type":"string","description":"The name of the field. Separate words with underscores."},"is_key_field":{"type":"string","description":"Is the key field for describing the Custom Content Type item or not. Mark as key fields only most important Content Type fields","enum":["yes","no"]},"field_type":{"type":"string","description":"The type of the field.","enum":["text","number","date","datetime","media","checkbox","select","radio","textarea"]},"save_as_timestamp":{"type":"boolean","description":"Whether to save the date/datetime field as a timestamp. Applicable only for date and datetime field types."},"value_format":{"type":"string","description":"For the media field type, specifies the format in which the value is stored in the DB (id - the attachment ID, url - the attachment URL, both - array with both ID and URL).","enum":["id","url","both"]},"options":{"type":"array","description":"The options for the fields with select, checkbox and radio types.","items":{"type":"string"}}}}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the Custom Content Type was successfully created."},"item_id":{"type":"integer","description":"The ID of the newly created Custom Content Type."},"cct_settings_url":{"type":"string","description":"The URL to the settings page of the newly created Custom Content Type in the WordPress admin."},"cct_items_list_url":{"type":"string","description":"The URL to the list of items for the newly created Custom Content Type in the WordPress admin."},"notices":{"type":"array","description":"An array of notices generated during the creation process.","items":{"type":"string"}},"next_tool":{"type":"string","description":"The identifier of the next recommended tool to use after creating the Custom Content Type."}},"meta":[]},{"id":"resource-get-configuration","name":"resource-get-configuration","label":"Get JetEngine Configuration","description":"Retrieve an overview of JetEngine post types, taxonomies, meta boxes, options pages, queries, relations, custom content types, REST API endpoints, and glossaries in JSON format.","type":"resource","input_schema":{"type":"object","properties":{"parts":{"type":"object","description":"Specific parts of the configuration to retrieve in the format config: true/false. If empty or not provided, empty array will be returned.","properties":{"post_types":{"type":"boolean","description":"Include registered JetEngine post types."},"taxonomies":{"type":"boolean","description":"Include registered JetEngine taxonomies."},"meta_boxes":{"type":"boolean","description":"Include meta boxes created with JetEngine."},"options_pages":{"type":"boolean","description":"Include JetEngine options pages."},"queries":{"type":"boolean","description":"Include Query Builder queries."},"relations":{"type":"boolean","description":"Include registered JetEngine relations."},"custom_content_types":{"type":"boolean","description":"Include Custom Content Types registered in JetEngine."},"rest_api_endpoints":{"type":"boolean","description":"Include REST API endpoints configured via the Rest API Listings module."},"glossaries":{"type":"boolean","description":"Include JetEngine glossaries."}}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the configuration data was collected successfully."},"post_types":{"type":"array","description":"Registered JetEngine post types.","items":{"type":"object"}},"taxonomies":{"type":"array","description":"Registered JetEngine taxonomies.","items":{"type":"object"}},"meta_boxes":{"type":"array","description":"Meta boxes created with JetEngine.","items":{"type":"object"}},"options_pages":{"type":"array","description":"JetEngine options pages.","items":{"type":"object"}},"queries":{"type":"array","description":"Query Builder queries.","items":{"type":"object"}},"relations":{"type":"array","description":"Registered JetEngine relations.","items":{"type":"object"}},"custom_content_types":{"type":"array","description":"Custom Content Types registered in JetEngine.","items":{"type":"object"}},"rest_api_endpoints":{"type":"array","description":"REST API endpoints configured via the Rest API Listings module.","items":{"type":"object"}},"glossaries":{"type":"array","description":"JetEngine glossaries.","items":{"type":"object"}}},"meta":[]},{"id":"resource-get-website-config","name":"resource-get-website-config","label":"Get Website Config","description":"Retrieve information about registered post types, taxonomies, and active plugins in JSON format.","type":"resource","input_schema":{"type":"object","properties":{"parts":{"type":"object","description":"Specific parts of the website configuration to retrieve. If empty or not provided, all sections will be returned.","properties":{"post_types":{"type":"boolean","description":"Include registered post types."},"taxonomies":{"type":"boolean","description":"Include registered taxonomies."},"active_plugins":{"type":"boolean","description":"Include active plugins."}}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the data was collected successfully."},"post_types":{"type":"array","description":"Registered post types.","items":{"type":"object"}},"taxonomies":{"type":"array","description":"Registered taxonomies.","items":{"type":"object"}},"active_plugins":{"type":"array","description":"Active plugins and their metadata.","items":{"type":"object"}}},"meta":[]},{"id":"resource-get-macros","name":"resource-get-macros","label":"Get JetEngine Macros","description":"Retrieve all JetEngine macros with their arguments and usage examples for AI assisted tooling.","type":"resource","input_schema":{"type":"object","properties":{"exclude":{"type":"array","description":"Optional list of macro IDs (tags) to exclude from the response.","items":{"type":"string"}}}},"output_schema":{"success":{"type":"boolean","description":"Whether the macros information was gathered successfully."},"macros":{"type":"array","description":"Collection of JetEngine macros available in the current environment.","items":{"type":"object","properties":{"id":{"type":"string","description":"Unique macros identifier (tag)."},"label":{"type":"string","description":"Human readable macros name."},"arguments":{"type":"array","description":"Arguments supported by the macros, listed in the order they should be provided.","items":{"type":"object","properties":{"key":{"type":"string","description":"Argument key."},"label":{"type":"string","description":"Human readable argument label."},"type":{"type":"string","description":"Expected argument input type."},"description":{"type":"string","description":"Additional details that describe the argument."},"default":{"type":"string","description":"Default value that will be used when the argument is omitted."},"options":{"type":"array","description":"Flat list of selectable options available for the argument.","items":{"type":"object","properties":{"value":{"type":"string","description":"Option value that should be inserted into the macros string."},"label":{"type":"string","description":"Human readable option label."}}}},"groups":{"type":"array","description":"Grouped options when the argument exposes nested option collections.","items":{"type":"object","properties":{"label":{"type":"string","description":"Group label."},"options":{"type":"array","items":{"type":"object","properties":{"value":{"type":"string"},"label":{"type":"string"}}}}}}}}}},"example":{"type":"string","description":"Example macros placeholder showing the expected usage."}}}}},"meta":[]},{"id":"tool-add-glossary","name":"tool-add-glossary","label":"Add Glossary","description":"Register a new JetEngine glossary with manually provided options. Always include at least one field object with both value and label properties. Only manual glossaries are supported by this tool.","type":"tool","input_schema":{"type":"object","properties":{"name":{"type":"string","description":"The human-readable name of the glossary."},"source":{"type":"string","description":"The data source for the glossary. Only the \"manual\" source is supported when using this tool.","enum":["manual"]},"fields":{"type":"array","description":"A list of glossary items. Each item must define both value and label. Up to 100 entries is recommended for optimal performance.","items":{"type":"object","required":["value","label"],"properties":{"value":{"type":"string","description":"The stored value of the glossary option. Must be unique within the glossary whenever possible. Important - all values should contain only lowercase Latin letters, numbers and \"-\" or \"_\" chars, without spaces and other special characters"},"label":{"type":"string","description":"The human-friendly label displayed for this option."},"is_checked":{"type":"boolean","description":"Optional. Mark as true to keep the option pre-selected by default."}}}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the glossary was created successfully."},"item_id":{"type":"integer","description":"The ID of the newly created glossary."},"glossary_settings_url":{"type":"string","description":"URL to manage the glossary inside the WordPress dashboard."},"notices":{"type":"array","description":"Any admin notices generated during the creation process.","items":{"type":"string"}}},"meta":[]},{"id":"tool-manage-modules","name":"tool-manage-modules","label":"Manage JetEngine Modules","description":"List active modules or activate/deactivate JetEngine modules.","type":"tool","input_schema":{"type":"object","properties":{"operation":{"type":"string","description":"Operation to perform: list active modules, activate modules, or deactivate modules.","enum":["list","activate","deactivate"],"default":"list"},"modules":{"type":"array","description":"Module slugs to activate or deactivate when the operation requires it.","items":{"type":"string"}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the requested operation was performed successfully."},"active_modules":{"type":"array","description":"The list of currently active JetEngine modules.","items":{"type":"object","properties":{"slug":{"type":"string","description":"The slug of the active module."},"name":{"type":"string","description":"The human-readable name of the active module."},"description":{"type":"string","description":"A brief description of the active module."}}}},"all_modules":{"type":"array","description":"The list of all available JetEngine modules.","items":{"type":"object","properties":{"slug":{"type":"string","description":"The slug of the module."},"name":{"type":"string","description":"The human-readable name of the module."},"description":{"type":"string","description":"A brief description of the module."}}}},"updated_modules":{"type":"array","description":"Modules that were changed during the operation.","items":{"type":"string"}},"invalid_modules":{"type":"array","description":"Modules that were requested but not recognized.","items":{"type":"string"}},"message":{"type":"string","description":"Additional information about the operation result."}},"meta":[]},{"id":"tool-add-listing","name":"tool-add-listing","label":"Add Listing Grid Item","description":"Create a JetEngine listing item connected to an existing Query Builder query.","type":"tool","input_schema":{"type":"object","properties":{"title":{"type":"string","description":"Listing title shown in the WordPress dashboard. When omitted the query name is used."},"query_id":{"type":"integer","description":"Existing Query Builder ID that will be used as the listing data source."},"view_type":{"type":"string","description":"Optional builder slug (elementor, bricks, twig, blocks). Use \"auto\" to pick the first available builder integration.","enum":["auto","elementor","bricks","twig","blocks"]}}},"output_schema":[],"meta":[]},{"id":"tool-add-cpt","name":"tool-add-cpt","label":"Add Post Type","description":"Register a new Post Type (CPT) with JetEngine. Provide the post type name inside general_settings.name. The slug will be generated from the name if you omit it. Select this tool only when USER clearly mentioned that he need a new custom post type. In other cases - look for more specific tools.","type":"tool","input_schema":{"type":"object","properties":{"general_settings":{"type":"object","description":"General settings for the post type such as the public label, slug and storage flags.","properties":{"name":{"type":"string","description":"Plural label shown in the WordPress admin."},"slug":{"type":"string","description":"Custom post type slug (max 20 lowercase characters). Generated from the name when omitted."},"custom_storage":{"type":"boolean","description":"Store CPT data inside a dedicated custom database table."},"show_edit_link":{"type":"boolean","description":"Display the \u201cEdit Post Type\u201d link inside the WordPress toolbar."},"hide_field_names":{"type":"boolean","description":"Hide field names on the edit screen to make the UI cleaner."},"delete_metadata":{"type":"boolean","description":"Delete all related metadata when the post type is removed."}}},"labels":{"type":"object","description":"Optional labels that override the default WordPress labels for the CPT."},"advanced_settings":{"type":"object","description":"Advanced visibility and capability settings (public, supports, menu_icon, etc.)."},"meta_fields":{"type":"array","description":"Meta field definitions. Pass JetEngine meta field objects or simplified items with name, type, title, options, etc.","items":{"type":"object","properties":{"object_type":{"type":"string","description":"If present with value \"field\", item is treated as a raw JetEngine field object."},"id":{"type":"integer"},"name":{"type":"string","description":"Field key (snake_case). Alias: field_name."},"field_name":{"type":"string"},"title":{"type":"string"},"label":{"type":"string"},"type":{"type":"string","enum":["text","number","date","datetime","datetime-local","time","media","checkbox","select","radio","textarea","repeater"]},"field_type":{"type":"string"},"description":{"type":"string"},"placeholder":{"type":"string"},"default":{"type":"string"},"is_required":{"type":"boolean"},"value_format":{"type":"string","description":"For media fields: id|url|both. For textarea fields: raw|plain_text|safe_html."},"options":{"type":"array","items":{"type":"string"},"description":"For select/checkbox/radio (simple list or \"value::label\" pairs)."},"choices":{"type":"array","items":{"type":"string"},"description":"Alternative to options."},"fields":{"type":"array","items":{"type":"object"}},"add_to_admin_column":{"type":"boolean"},"admin_column_position":{"type":"integer"},"column_prefix":{"type":"string"},"column_suffix":{"type":"string"},"is_sortable":{"type":"boolean"},"sort_by_field":{"type":"string"}}}},"admin_columns":{"type":"array","description":"Optional admin columns configuration. Leave empty to auto-generate from meta_fields flagged with add_to_admin_column.","items":{"type":"object","properties":{"title":{"type":"string"},"type":{"type":"string","description":"e.g. meta_value, taxonomy, callback"},"meta_field":{"type":"string"},"taxonomy":{"type":"string"},"callback":{"type":"string"},"position":{"type":"integer"},"prefix":{"type":"string"},"suffix":{"type":"string"},"is_sortable":{"type":"boolean"},"sort_by_field":{"type":"string"},"is_num":{"type":"boolean"}}}},"admin_filters":{"type":"array","description":"Optional admin filters configuration for the post list screen.","items":{"type":"object"}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the CPT was created successfully."},"item_id":{"type":"integer","description":"Internal database ID of the created CPT record."},"cpt_settings_url":{"type":"string","description":"Link to edit the CPT inside the WordPress dashboard."},"cpt_items_list_url":{"type":"string","description":"Link to the WordPress list table that displays posts of the new CPT."},"notices":{"type":"array","description":"Array of JetEngine notices triggered during creation (each notice contains type and message)."},"next_tool":{"type":"string","description":"Suggested MCP tool to run after creating the CPT."}},"meta":[]},{"id":"tool-add-meta-box","name":"tool-add-meta-box","label":"Add Meta Box","description":"Create a JetEngine Meta Box with custom fields. Always provide general_settings.name and describe the fields in meta_fields. The tool automatically enables the necessary visibility conditions when you supply their configuration.","type":"tool","input_schema":{"type":"object","properties":{"general_settings":{"type":"object","description":"General settings such as the title, target object, and condition configuration.","properties":{"name":{"type":"string","description":"Meta box title shown in the WordPress dashboard."},"object_type":{"type":"string","description":"Object type where the meta box should appear.","enum":["post","taxonomy","user"]},"show_edit_link":{"type":"boolean","description":"Display the \u201cEdit meta box\u201d link in the toolbar."},"hide_field_names":{"type":"boolean","description":"Hide field names on the edit screen."},"delete_metadata":{"type":"boolean","description":"Delete stored metadata when the meta box or its fields are removed."},"allowed_post_type":{"type":"array","description":"Post type slugs that should display the meta box (only for object_type \"post\").","items":{"type":"string"}},"allowed_tax":{"type":"array","description":"Taxonomy slugs that should display the meta box (only for object_type \"taxonomy\").","items":{"type":"string"}},"allowed_user_screens":{"type":"string","description":"For user meta boxes choose whether fields appear on Edit User only or Edit User & Profile.","enum":["edit","edit-profile"]},"active_conditions":{"type":"array","description":"List of enabled condition keys (allowed_posts, excluded_posts, include_roles, exclude_roles, post_has_terms, etc.). Missing keys are added automatically when related settings are provided.","items":{"type":"string"}},"allowed_posts":{"type":"array","description":"Specific post IDs that should display the meta box (activates allowed_posts condition).","items":{"type":"integer"}},"excluded_posts":{"type":"array","description":"Post IDs where the meta box must be hidden (activates excluded_posts condition).","items":{"type":"integer"}},"include_roles":{"type":"array","description":"User roles that should see the meta box (activates include_roles condition).","items":{"type":"string"}},"exclude_roles":{"type":"array","description":"User roles that should be prevented from seeing the meta box (activates exclude_roles condition).","items":{"type":"string"}},"post_has_terms__tax":{"type":"string","description":"Taxonomy slug used for the post_has_terms condition."},"post_has_terms__terms":{"type":"array","description":"Term IDs or slugs to compare in the post_has_terms condition.","items":{"type":"string"}}},"additionalProperties":true},"meta_fields":{"type":"array","description":"Meta field definitions saved inside the meta box. Pass full JetEngine field arrays (object_type =\u003E field) or simplified descriptors with name, type, label, options, etc.","items":{"type":"object","properties":{"object_type":{"type":"string","description":"Set to \"field\" when providing full JetEngine meta field data."},"id":{"type":"integer","description":"Optional field identifier. Generated automatically when omitted."},"name":{"type":"string","description":"Field key (snake_case)."},"field_name":{"type":"string","description":"Alias for name when using simplified descriptors."},"title":{"type":"string","description":"Field label displayed in the UI."},"label":{"type":"string"},"type":{"type":"string","description":"JetEngine field type slug (text, textarea, select, repeater, etc.)."},"field_type":{"type":"string","description":"Alternative key for the field type."},"description":{"type":"string"},"placeholder":{"type":"string"},"default":{"type":"string","description":"Default value stored for the field."},"is_required":{"type":"boolean"},"quick_editable":{"type":"boolean"},"value_format":{"type":"string","description":"For media fields use id, url, or both; for textarea fields use raw, plain_text, or safe_html."},"taxonomy":{"type":"string","description":"Taxonomy slug for taxonomy fields or taxonomy option source."},"appearance":{"type":"string","description":"Taxonomy field appearance (select, radio, checkboxes)."},"multiple":{"type":"boolean","description":"Allow multiple values for taxonomy/select fields."},"allow_null":{"type":"boolean","description":"Allow empty value for single-selection taxonomy fields."},"return_value":{"type":"string","description":"Taxonomy return value (term_id, term_slug, term_name)."},"load_terms":{"type":"boolean","description":"Prefill taxonomy field from current object term relationships."},"save_terms":{"type":"boolean","description":"Sync taxonomy field value into object-term relationships on save."},"options":{"type":"array","description":"Advanced options array when using manual options.","items":{"type":"object"}},"choices":{"type":"array","description":"Alternative list of options (array of values or value::label strings).","items":{"type":"string"}},"fields":{"type":"array","description":"Nested fields for repeater-like types.","items":{"type":"object"}},"conditions":{"type":"array","description":"Optional field visibility conditions.","items":{"type":"object"}}},"additionalProperties":true}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the meta box was created successfully."},"item_id":{"type":"string","description":"Internal ID of the created meta box."},"meta_box_url":{"type":"string","description":"Admin URL to edit the newly created meta box."},"meta_boxes_list_url":{"type":"string","description":"Admin URL that lists all JetEngine meta boxes."},"notices":{"type":"array","description":"JetEngine notices generated during creation (each notice contains type and message).","items":{"type":"object"}},"next_tool":{"type":"string","description":"Suggested MCP tool to run after creating the meta box."}},"meta":[]},{"id":"tool-add-taxonomy","name":"tool-add-taxonomy","label":"Add Taxonomy","description":"Register a new taxonomy in JetEngine. Provide the taxonomy name inside general_settings.name and assign it to one or more post types via general_settings.object_type.","type":"tool","input_schema":{"type":"object","properties":{"general_settings":{"type":"object","description":"General settings such as the taxonomy label, slug, and assigned post types.","properties":{"name":{"type":"string","description":"Plural label displayed in the WordPress admin."},"slug":{"type":"string","description":"Taxonomy slug (max 32 lowercase characters). Generated from the name when omitted."},"object_type":{"type":"array","description":"List of post type slugs to attach this taxonomy to. Accepts a single string or array.","items":{"type":"string"}},"show_edit_link":{"type":"boolean","description":"Display the \u201cEdit Taxonomy\u201d toolbar link."},"hide_field_names":{"type":"boolean","description":"Hide field names inside the edit form."},"delete_metadata":{"type":"boolean","description":"Remove stored term metadata when the taxonomy is deleted."}},"additionalProperties":true},"labels":{"type":"object","description":"Optional taxonomy labels that override the WordPress defaults.","properties":{"singular_name":{"type":"string"},"menu_name":{"type":"string"},"all_items":{"type":"string"},"edit_item":{"type":"string"},"view_item":{"type":"string"},"update_item":{"type":"string"},"add_new_item":{"type":"string"},"new_item_name":{"type":"string"},"parent_item":{"type":"string"},"parent_item_colon":{"type":"string"},"search_items":{"type":"string"},"popular_items":{"type":"string"},"separate_items_with_commas":{"type":"string"},"add_or_remove_items":{"type":"string"},"choose_from_most_used":{"type":"string"},"not_found":{"type":"string"},"back_to_items":{"type":"string"}},"additionalProperties":true},"advanced_settings":{"type":"object","description":"Advanced visibility, rewrite, and capability settings.","properties":{"public":{"type":"boolean"},"publicly_queryable":{"type":"boolean"},"show_ui":{"type":"boolean"},"show_in_menu":{"type":"boolean"},"show_in_nav_menus":{"type":"boolean"},"show_in_rest":{"type":"boolean"},"query_var":{"type":["boolean","string"]},"rewrite":{"type":["boolean","object"]},"with_front":{"type":"boolean"},"capability_type":{"type":"string"},"hierarchical":{"type":"boolean"},"rewrite_slug":{"type":"string"},"rewrite_hierarchical":{"type":"boolean"},"description":{"type":"string"}},"additionalProperties":true},"meta_fields":{"type":"array","description":"Meta field definitions saved for taxonomy terms. Provide JetEngine field objects or simplified descriptors with name, type, label, options, etc.","items":{"type":"object","properties":{"object_type":{"type":"string"},"id":{"type":"integer"},"name":{"type":"string"},"field_name":{"type":"string"},"title":{"type":"string"},"label":{"type":"string"},"type":{"type":"string"},"field_type":{"type":"string"},"description":{"type":"string"},"placeholder":{"type":"string"},"default":{"type":"string"},"is_required":{"type":"boolean"},"value_format":{"type":"string","description":"For media fields: id|url|both. For textarea fields: raw|plain_text|safe_html."},"options":{"type":"array","items":{"type":["string","object"]}},"choices":{"type":"array","items":{"type":"string"}},"fields":{"type":"array","items":{"type":"object"}}},"additionalProperties":true}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the taxonomy was created successfully."},"item_id":{"type":"integer","description":"Internal database ID of the taxonomy."},"taxonomy_settings_url":{"type":"string","description":"Link to edit the taxonomy inside the WordPress dashboard."},"taxonomy_terms_list_url":{"type":"string","description":"Link to manage the taxonomy terms in WordPress."},"notices":{"type":"array","description":"Array of JetEngine notices triggered during creation."},"next_tool":{"type":"string","description":"Suggested MCP tool to run after creating the taxonomy."}},"meta":[]},{"id":"tool-add-query","name":"tool-add-query","label":"Add Query","description":"Register a new Query for Crocoblock Query Builder and return data in a standardized format. You MUST ALWAYS include the query_args object when calling this tool. Requests without query_args are invalid and will be rejected. For query_type: \"sql\", query_args must contain a non-empty sql string. For other types, query_args must contain the appropriate query arguments (WP_Query-style for posts, terms, users, etc.). Do not call this tool if you cannot provide query_args. Ask for the missing details first. Valid examples. SQL: {\"name\":\"Recent orders\",\"query_type\":\"sql\",\"query_args\":{\"sql\":\"SELECT * FROM wp_posts WHERE post_type='shop_order' LIMIT 10\"}}. Posts: {\"name\":\"Latest posts\",\"query_type\":\"posts\",\"query_args\":{\"post_type\":\"post\",\"posts_per_page\":5}} Invalid example (will be rejected) - {\"name\":\"Latest posts\",\"query_type\":\"posts\"} \u2190 missing query_args. Macros supported: Use macros from the conversation context for contextual params (IDs, user, dates). Prefer macros everywhere possible to make queries dynamic. ","type":"tool","input_schema":{"type":"object","properties":{"name":{"type":"string","description":"The name of the Query."},"query_type":{"type":"string","description":"The type of the Query. This determines how the query will be processed and what data it will return.","enum":["sql","posts","terms","users","comments","repeater","current-wp-query","merged-query","relations-query","custom-content-type","rest-api"]},"query_args":{"type":"object","description":"REQUIRED. The query arguments object. Calls without query_args are invalid and will be rejected. For query_type: \"sql\", query_args must be { \"sql\": \"\u003Cnon-empty SQL string\u003E\" }. For query_type: \"posts\", terms, users, or comments, query_args must mirror WP_Query-style arguments such as post_type, posts_per_page, orderby, order, tax_query, and meta_query. For query_type: \"custom-content-type\" (CCT), query_args must follow WP_Query-style for post types with CCT fields expressed via meta_query, for example { \"post_type\": \"cct-slug/name\", \"meta_query\": [ { \"key\": \"cct_field\", \"value\": \"some_value\" } ], \"posts_per_page\": 10, \"orderby\": \"date\", \"order\": \"DESC\" }. All other query types should also format query_args into WP_Query-style wherever possible. Valid examples include SQL: { \"