440-//# sourceURL=jet-popup-frontend-js-extra </script> <script id="jet-popup-frontend-js" src="https://www.apeejay.edu/architecture/wp-content/uploads/siteground-optimizer-assets/jet-popup-frontend.min.js?ver=2.2.2"></script> <script id="jet-engine-compatibility-angie-js-extra"> var jetEngineCompatibilityAngie = {"features":[{"id":"tool-add-cct","name":"tool-add-cct","label":"Add Custom Content Type","description":"This feature allows you to register a new Custom Content Type. Custom Content Type is a performant content storage, which can replace Custom Post Types for some cases. All the Custom Content Type data stored in the separate DB table, so it`s an efficient way to store large amounts of the information.","type":"tool","input_schema":{"type":"object","properties":{"name":{"type":"string","description":"The name of the Custom Content Type."},"slug":{"type":"string","description":"The slug of the Custom Content Type. Should contain only lowercase letters and underscores."},"fields":{"type":"array","description":"The fields of the Custom Content Type. Each field should have a name, type, is_key_field flag (yes/no) and optionally options for select, checkbox, and radio types.","items":{"type":"object","properties":{"field_name":{"type":"string","description":"The name of the field. Separate words with underscores."},"is_key_field":{"type":"string","description":"Is the key field for describing the Custom Content Type item or not. Mark as key fields only most important Content Type fields","enum":["yes","no"]},"field_type":{"type":"string","description":"The type of the field.","enum":["text","number","date","datetime","media","checkbox","select","radio","textarea"]},"save_as_timestamp":{"type":"boolean","description":"Whether to save the date/datetime field as a timestamp. Applicable only for date and datetime field types."},"value_format":{"type":"string","description":"For the media field type, specifies the format in which the value is stored in the DB (id - the attachment ID, url - the attachment URL, both - array with both ID and URL).","enum":["id","url","both"]},"options":{"type":"array","description":"The options for the fields with select, checkbox and radio types.","items":{"type":"string"}}}}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the Custom Content Type was successfully created."},"item_id":{"type":"integer","description":"The ID of the newly created Custom Content Type."},"cct_settings_url":{"type":"string","description":"The URL to the settings page of the newly created Custom Content Type in the WordPress admin."},"cct_items_list_url":{"type":"string","description":"The URL to the list of items for the newly created Custom Content Type in the WordPress admin."},"notices":{"type":"array","description":"An array of notices generated during the creation process.","items":{"type":"string"}},"next_tool":{"type":"string","description":"The identifier of the next recommended tool to use after creating the Custom Content Type."}},"meta":[]},{"id":"resource-get-configuration","name":"resource-get-configuration","label":"Get JetEngine Configuration","description":"Retrieve an overview of JetEngine post types, taxonomies, meta boxes, options pages, queries, relations, custom content types, REST API endpoints, and glossaries in JSON format.","type":"resource","input_schema":{"type":"object","properties":{"parts":{"type":"object","description":"Specific parts of the configuration to retrieve in the format config: true/false. If empty or not provided, empty array will be returned.","properties":{"post_types":{"type":"boolean","description":"Include registered JetEngine post types."},"taxonomies":{"type":"boolean","description":"Include registered JetEngine taxonomies."},"meta_boxes":{"type":"boolean","description":"Include meta boxes created with JetEngine."},"options_pages":{"type":"boolean","description":"Include JetEngine options pages."},"queries":{"type":"boolean","descriptio