iguration.","properties":{"name":{"type":"string","description":"Meta box title shown in the WordPress dashboard."},"object_type":{"type":"string","description":"Object type where the meta box should appear.","enum":["post","taxonomy","user"]},"show_edit_link":{"type":"boolean","description":"Display the \u201cEdit meta box\u201d link in the toolbar."},"hide_field_names":{"type":"boolean","description":"Hide field names on the edit screen."},"delete_metadata":{"type":"boolean","description":"Delete stored metadata when the meta box or its fields are removed."},"allowed_post_type":{"type":"array","description":"Post type slugs that should display the meta box (only for object_type \"post\").","items":{"type":"string"}},"allowed_tax":{"type":"array","description":"Taxonomy slugs that should display the meta box (only for object_type \"taxonomy\").","items":{"type":"string"}},"allowed_user_screens":{"type":"string","description":"For user meta boxes choose whether fields appear on Edit User only or Edit User & Profile.","enum":["edit","edit-profile"]},"active_conditions":{"type":"array","description":"List of enabled condition keys (allowed_posts, excluded_posts, include_roles, exclude_roles, post_has_terms, etc.). Missing keys are added automatically when related settings are provided.","items":{"type":"string"}},"allowed_posts":{"type":"array","description":"Specific post IDs that should display the meta box (activates allowed_posts condition).","items":{"type":"integer"}},"excluded_posts":{"type":"array","description":"Post IDs where the meta box must be hidden (activates excluded_posts condition).","items":{"type":"integer"}},"include_roles":{"type":"array","description":"User roles that should see the meta box (activates include_roles condition).","items":{"type":"string"}},"exclude_roles":{"type":"array","description":"User roles that should be prevented from seeing the meta box (activates exclude_roles condition).","items":{"type":"string"}},"post_has_terms__tax