tion":"Taxonomy return value (term_id, term_slug, term_name)."},"load_terms":{"type":"boolean","description":"Prefill taxonomy field from current object term relationships."},"save_terms":{"type":"boolean","description":"Sync taxonomy field value into object-term relationships on save."},"options":{"type":"array","description":"Advanced options array when using manual options.","items":{"type":"object"}},"choices":{"type":"array","description":"Alternative list of options (array of values or value::label strings).","items":{"type":"string"}},"fields":{"type":"array","description":"Nested fields for repeater-like types.","items":{"type":"object"}},"conditions":{"type":"array","description":"Optional field visibility conditions.","items":{"type":"object"}}},"additionalProperties":true}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the meta box was created successfully."},"item_id":{"type":"string","description":"Internal ID of the created meta box."},"meta_box_url":{"type":"string","description":"Admin URL to edit the newly created meta box."},"meta_boxes_list_url":{"type":"string","description":"Admin URL that lists all JetEngine meta boxes."},"notices":{"type":"array","description":"JetEngine notices generated during creation (each notice contains type and message).","items":{"type":"object"}},"next_tool":{"type":"string","description":"Suggested MCP tool to run after creating the meta box."}},"meta":[]},{"id":"tool-add-taxonomy","name":"tool-add-taxonomy","label":"Add Taxonomy","description":"Register a new taxonomy in JetEngine. Provide the taxonomy name inside general_settings.name and assign it to one or more post types via general_settings.object_type.","type":"tool","input_schema":{"type":"object","properties":{"general_settings":{"type":"object","description":"General settings such as the taxonomy label, slug, and assigned post types.","properties":{"name":{"type":"string","description":"Plural label displayed in the WordPress admin."},"slug":{"type":"string","description":"Taxonomy slug (max 32 lowercase characters). Generated from the name when omitted."},"object_type":{"type":"array","description":"List of post type slugs to attach this taxonomy to. Accepts a single string or array.","items":{"type":"string"}},"show_edit_link":{"type":"boolean","description":"Display the \u201cEdit Taxonomy\u201d toolbar link."},"hide_field_names":{"type":"boolean","description":"Hide field names inside the edit form."},"delete_metadata":{"type":"boolean","description":"Remove stored term metadata when the taxonomy is deleted."}},"additionalProperties":true},"labels":{"type":"object","description":"Optional taxonomy labels that override the WordPress defaults.","properties":{"singular_name":{"type":"string"},"menu_name":{"type":"string"},"all_items":{"type":"string"},"edit_item":{"type":"string"},"view_item":{"type":"string"},"update_item":{"type":"string"},"add_new_item":{"type":"string"},"new_item_name":{"type":"string"},"parent_item":{"type":"string"},"parent_item_colon":{"type":"string"},"search_items":{"type":"string"},"popular_items":{"type":"string"},"separate_items_with_commas":{"type":"string"},"add_or_remove_items":{"type":"string"},"choose_from_most_used":{"type":"string"},"not_found":{"type":"string"},"back_to_items":{"type":"string"}},"additionalProperties":true},"advanced_settings":{"type":"object","description":"Advanced visibility, rewrite, and capability settings.","properties":{"public":{"type":"boolean"},"publicly_queryable":{"type":"boolean"},"show_ui":{"type":"boolean"},"show_in_menu":{"type":"boolean"},"show_in_nav_menus":{"type":"boolean"},"show_in_rest":{"type":"boolean"},"query_var":{"type":["boolean","string"]},"rewrite":{"type":["boolean","object"]},"with_front":{"type":"boolean"},"capability_type":{"type":"string"},"hierarchical":{"type":"boolean"},"rewrite_slug":{"type":"string"},"rewrite_hierarchical":{"type":"boolean"},"description":{"type":"string"}},"additionalProperties":true},"meta_fields":{"type":"array","description":"Meta field definitions saved for taxonomy terms. Provide JetEngine field objects or simplified descriptors with name, type, label, options, etc.","items":{"type":"object","properties":{"object_type":{"type":"string"},"id":{"type":"integer"},"name":{"type":"string"},"field_name":{"type":"string"},"title":{"type":"string"},"label":{"type":"string"},"type":{"type":"string"},"field_type":{"type":"string"},"description":{"type":"string"},"placeholder":{"type":"string"},"default":{"type":"string"},"is_required":{"type":"boolean"},"value_format":{"type":"string","description":"For media fields: id|url|both. For textarea fields: raw|plain_text|safe_html."},"options":{"type":"array","items":{"type":["string","object"]}},"choices":{"type":"array","items":{"type":"string"}},"fields":{"type":"array","items":{"type":"object"}}},"additionalProperties":true}}}},"output_schema":{"success":{"type":"boolean","description":"Indicates whether the taxonomy was created successfully."},"item_id":{"type":"integer","description":"Internal database ID of the taxonomy."},"taxonomy_settings_url":{"type":"string","description":"Link to edit the taxonomy inside the WordPress dashboard."},"taxonomy_terms_list_url":{"type":"string","description":"Link to manage the taxonomy terms in WordPress."},"notices":{"type":"array","description":"Array of JetEngine notices triggered during creation."},"next_tool":{"type":"string","description":"Suggested MCP tool to run after creating the taxonomy."}},"meta":[]},{"id":"tool-add-query","name":"tool-add-query","label":"Add Query","description":"Register a new Query for Crocoblock Query Builder and return data in a standardized format. You MUST ALWAYS include the query_args object when calling this tool. Requests without query_args are invalid and will be rejected. For query_type: \"sql\", query_args must contain a non-empty sql string. For other types, query_args must contain the appropriate query arguments (WP_Query-style for posts, terms, users, etc.). Do not call this tool if you cannot provide query_args. Ask for the missing details first. Valid examples. SQL: {\"name\":\"Recent orders\",\"query_type\":\"sql\",\"query_args\":{\"sql\":\"SELECT * FROM wp_posts WHERE post_type='shop_order' LIMIT 10\"}}. Posts: {\"name\":\"Latest posts\",\"query_type\":\"posts\",\"query_args\":{\"post_type\":\"post\",\"posts_per_page\":5}} Invalid example (will be rejected) - {\"name\":\"Latest posts\",\"query_type\":\"posts\"} \u2190 missing query_args. Macros supported: Use macros from the conversation context for contextual params (IDs, user, dates). Prefer macros everywhere possible to make queries dynamic. ","type":"tool","input_schema":{"type":"object","properties":{"name":{"type":"string","description":"The name of the Query."},"query_type":{"type":"string","description":"The type of the Query. This determines how the query will be processed and what data it will return.","enum":["sql","posts","terms","users","comments","repeater","current-wp-query","merged-query","relations-query","custom-content-type","rest-api"]},"query_args":{"type":"object","description":"REQUIRED. The query arguments object. Calls without query_args are invalid and will be rejected. For query_type: \"sql\", query_args must be { \"sql\": \"\u003Cnon-empty SQL string\u003E\" }. For query_type: \"posts\", terms, users, or comments, query_args must mirror WP_Query-style arguments such as post_type, posts_per_page, orderby, order, tax_query, and meta_query. For query_type: \"custom-content-type\" (CCT), query_args must follow WP_Query-style for post types with CCT fields expressed via meta_query, for example { \"post_type\": \"cct-slug/name\", \"meta_query\": [ { \"key\": \"cct_field\", \"value\": \"some_value\" } ], \"posts_per_page\": 10, \"orderby\": \"date\", \"order\": \"DESC\" }. All other query types should also format query_args into WP_Query-style wherever possible. Valid examples include SQL: { \"